examples:
//-- requests permission to change links, then breaks the link
//-- between the prim and the rest of the object, on touch.
default
{
touch_start
(
integer
vIntTouched
)
{
llRequestPermissions
(
llGetOwner
(),
PERMISSION_CHANGE_LINKS
);
}
run_time_permissions
(
integer
perm
)
{
if
(
perm
&
PERMISSION_CHANGE_LINKS
)
{
llBreakLink
(
llGetLinkNumber
());
}
}
}
